actions.script:
defaults = {}
if (!organizationPartyId && workEffortId) organizationPartyId = ec.service.sync().name('mantle.work.ProjectServices.get#ProjectSettings')
        .parameters({workEffortId}).call()?.organizationPartyId || null
if (!organizationPartyId) return
const row = ec.entity.find('mantle.party.PartySetting').condition('partyId', organizationPartyId)
        .condition('partySettingTypeId', 'ProjRepositoryDefaults').disableAuthz().one()
if (!row?.settingValue) return
try {
    const parsed = JSON.parse(row.settingValue)
    if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) defaults = parsed
    else ec.logger.error(`Repository defaults of ${organizationPartyId}: ProjRepositoryDefaults is not a JSON object, skipped`)
} catch (err) {
    ec.logger.error(`Repository defaults of ${organizationPartyId}: ProjRepositoryDefaults is not JSON, skipped: ${err}`)
}

let values = defaults
if (values == null) values = ec.service.sync().name('mantle.work.GitServices.get#RepositoryDefaults').parameters({workEffortId}).call()?.defaults || {}
if (!values || !Object.keys(values).length) return
const repo = ec.entity.find('moqui.resource.GitRepository').condition('repositoryId', repositoryId).disableAuthz().one()
if (repo == null) return
const yes = (value) => value === true || value === 'Y' || value === 'true'
const part = (name, run) => {
    ec.message.pushErrors()
    try {
        run()
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
    } catch (err) {
        ec.logger.error(`Repository defaults of ${repositoryId}: ${name} not applied: ${err && err.message ? err.message : err}`)
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
}
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    if (['GmmMerge', 'GmmSquash'].includes(values.mergeMethod) && repo.defaultMergeMethodEnumId !== values.mergeMethod) part('the merge method', () => {
        repo.defaultMergeMethodEnumId = values.mergeMethod
        repo.update()
    })
    if (yes(values.protectDefault)) part('the default branch rule', () => {
        const pattern = repo.branch || 'main'
        const existing = ec.entity.find('moqui.resource.GitBranchRule').condition({repositoryId, refPattern: pattern}).disableAuthz().count()
        if (existing > 0) return
        ec.service.sync().name('org.moqui.impl.GitServices.store#GitBranchRule').parameters({repositoryId, refPattern: pattern,
            allowForcePush: 'N', allowDelete: 'N', requireMergeRequest: yes(values.requireMergeRequest) ? 'Y' : 'N',
            requiredApprovals: Math.max(0, Number(values.approvals || 0) || 0), dismissStaleApprovals: yes(values.dismissStale) ? 'Y' : 'N'}).call()
    })
} finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }

const prefixes = new Set(projectIdList ?? [])
const keywords = /^(fix|fixes|fixed|close|closes|closed|resolve|resolves|resolved)$/i
const fromText = new Map()
const word = /[A-Za-z0-9][A-Za-z0-9_-]*/g
let match
let previous = null
let candidates = 0
while ((match = word.exec(text ?? '')) !== null && candidates < 50) {
    const token = match[0].replace(/[-_]+$/, '')
    const dash = token.indexOf('-')
    if (dash > 0 && prefixes.has(token.substring(0, dash))) {
        candidates++
        const complete = previous != null && keywords.test(previous)
        fromText.set(token, (fromText.get(token) ?? false) || complete)
    }
    previous = token
}
const fromTrailers = new Set()
for (const value of trailerValues ?? []) {
    for (const id of String(value).split(/[\s,]+/)) {
        if (id) fromTrailers.add(id)
    }
}
textIds = Array.from(fromText.keys())
trailerIds = Array.from(fromTrailers)
completeIds = Array.from(fromText.entries()).filter(([, complete]) => complete).map(([id]) => id)

service-call.in-map:
{workEffortId:workEffortId,
                    repositoryId:repositoryId, refName:refName, refType:refType, objectId:objectId,
                    linkSourceEnumId:linkSourceEnumId, linkedByUserId:ec.user.userId, linkedDate:ec.user.nowTimestamp}

actions.script:
const short = refName.replace(/^refs\/(heads|tags)\//, '')
if (isTag) {
    candidateIds = [short.split('/')[0]]
} else {
    // the last path segment, then each prefix of it that ends before a '-', longest first
    const segment = short.split('/').pop()
    candidateIds = []
    let end = segment.length
    while (end > 0) {
        candidateIds.push(segment.substring(0, end))
        end = segment.lastIndexOf('-', end - 1)
    }
}

workEffortIdList = []
const mr = ec.entity.find('moqui.resource.GitMergeRequest').condition('mergeRequestId', mergeRequestId).disableAuthz().one()
if (mr == null) { ec.message.addError(ec.resource.expand('Merge request ${mergeRequestId} not found', '', {mergeRequestId})); return }
const projectOut = ec.service.sync().name('mantle.work.GitServices.get#RepositoryProjects').parameters({repositoryId: mr.repositoryId}).disableAuthz().call()
const projectIds = Array.from(projectOut?.projectIdList || [])
if (!projectIds.length) return
const found = new Map()
// the source branch's task: the last path segment, then each prefix of it that ends before a '-', longest first
const segment = String(mr.sourceRef || '').split('/').pop()
const candidates = []
for (let end = segment.length; end > 0; end = segment.lastIndexOf('-', end - 1)) candidates.push(segment.substring(0, end))
if (candidates.length) {
    const rows = Array.from(ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', 'in', candidates)
            .condition('workEffortTypeEnumId', 'WetTask').condition('rootWorkEffortId', 'in', projectIds)
            .selectField('workEffortId,rootWorkEffortId').disableAuthz().list())
    const named = candidates.map((id) => rows.find((row) => row.workEffortId === id)).find((row) => row)
    if (named) found.set(named.workEffortId, {rootWorkEffortId: named.rootWorkEffortId, source: 'WglsMergeRequestBranch', complete: false})
}
const refs = ec.service.sync().name('mantle.work.GitServices.find#TaskReferences').parameters({repositoryId: mr.repositoryId,
    text: [mr.title || '', mr.description || ''].join('\n'), projectIdList: projectIds}).disableAuthz().call()
const textIds = []
for (const reference of Array.from(refs?.referenceList || [])) {
    if (reference.linkSourceEnumId !== 'WglsMessage') continue
    textIds.push(reference.workEffortId)
    const had = found.get(reference.workEffortId)
    if (had) had.complete = had.complete || !!reference.complete
    else found.set(reference.workEffortId, {rootWorkEffortId: reference.rootWorkEffortId, source: 'WglsMergeRequestText', complete: !!reference.complete})
}
// the project's choice: every linked item completes on merge
const moves = {}
const movesOf = (projectId) => {
    if (!(projectId in moves)) moves[projectId] = ec.service.sync().name('mantle.work.ProjectServices.get#ProjectSettings')
            .parameters({workEffortId: projectId}).disableAuthz().call()?.settings?.WstMergeRequestMoves === 'Y'
    return moves[projectId]
}
const existing = Array.from(ec.entity.find('mantle.work.effort.WorkEffortGitMergeRequest').condition('mergeRequestId', mergeRequestId).disableAuthz().list())
const now = ec.user.nowTimestamp
for (const [workEffortId, link] of found) {
    const complete = link.complete || (completeItems != null ? !!completeItems : movesOf(link.rootWorkEffortId))
    const row = existing.find((one) => one.workEffortId === workEffortId)
    if (row) {
        if ((row.completeOnMerge === 'Y') !== complete && row.linkSourceEnumId !== 'WglsExplicit') { row.completeOnMerge = complete ? 'Y' : 'N'; row.update() }
    } else {
        ec.service.sync().name('create#mantle.work.effort.WorkEffortGitMergeRequest').parameters({workEffortId, mergeRequestId,
            repositoryId: mr.repositoryId, linkSourceEnumId: link.source, completeOnMerge: complete ? 'Y' : 'N',
            linkedByUserId: ec.user.userId || null, linkedDate: now}).disableAuthz().call()
    }
    workEffortIdList.push(workEffortId)
}
// a key taken out of the text takes its link with it
for (const row of existing) {
    if (row.linkSourceEnumId === 'WglsMergeRequestText' && !found.has(row.workEffortId)) row.delete()
    else if (!found.has(row.workEffortId)) workEffortIdList.push(row.workEffortId)
}

const mr = ec.entity.find('moqui.resource.GitMergeRequest').condition('mergeRequestId', mergeRequestId).disableAuthz().one()
const access = mr ? ec.service.sync().name('org.moqui.impl.GitServices.get#GitRepositoryAccess').parameters({repositoryId: mr.repositoryId}).call() : null
if (!mr || !access?.canView) { ec.message.addError(ec.resource.expand('Merge request ${mergeRequestId} not found', '', {mergeRequestId})); return }
const task = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).one()
if (task == null || task.workEffortTypeEnumId !== 'WetTask') { ec.message.addError(ec.resource.expand('Work item ${workEffortId} not found', '', {workEffortId})); return }
const row = ec.entity.find('mantle.work.effort.WorkEffortGitMergeRequest').condition({workEffortId, mergeRequestId}).disableAuthz().one()
const complete = completeOnMerge === 'Y' || completeOnMerge === true ? 'Y' : 'N'
if (row) { row.linkSourceEnumId = 'WglsExplicit'; row.completeOnMerge = complete; row.update(); return }
ec.service.sync().name('create#mantle.work.effort.WorkEffortGitMergeRequest').parameters({workEffortId, mergeRequestId, repositoryId: mr.repositoryId,
    linkSourceEnumId: 'WglsExplicit', completeOnMerge: complete, linkedByUserId: ec.user.userId || null, linkedDate: ec.user.nowTimestamp}).disableAuthz().call()

const mr = ec.entity.find('moqui.resource.GitMergeRequest').condition('mergeRequestId', mergeRequestId).disableAuthz().one()
const access = mr ? ec.service.sync().name('org.moqui.impl.GitServices.get#GitRepositoryAccess').parameters({repositoryId: mr.repositoryId}).call() : null
if (!mr || !access?.canView) { ec.message.addError(ec.resource.expand('Merge request ${mergeRequestId} not found', '', {mergeRequestId})); return }
ec.entity.find('mantle.work.effort.WorkEffortGitMergeRequest').condition({workEffortId, mergeRequestId}).disableAuthz().deleteAll()

itemList = []
const mr = ec.entity.find('moqui.resource.GitMergeRequest').condition('mergeRequestId', mergeRequestId).disableAuthz().one()
const access = mr ? ec.service.sync().name('org.moqui.impl.GitServices.get#GitRepositoryAccess').parameters({repositoryId: mr.repositoryId}).call() : null
if (!mr || !access?.canView) { ec.message.addError(ec.resource.expand('Merge request ${mergeRequestId} not found', '', {mergeRequestId})); return }
const nameOf = (table, field, id) => id ? ec.entity.find(table).condition(field, id).useCache(true).disableAuthz().one()?.description || id : null
for (const link of Array.from(ec.entity.find('mantle.work.effort.WorkEffortGitMergeRequest').condition('mergeRequestId', mergeRequestId)
        .orderBy('workEffortId').disableAuthz().list())) {
    const task = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', link.workEffortId).disableAuthz().one()
    itemList.push({workEffortId: link.workEffortId, workEffortName: task?.workEffortName || '', statusId: task?.statusId || null,
        status: nameOf('moqui.basic.StatusItem', 'statusId', task?.statusId), rootWorkEffortId: task?.rootWorkEffortId || null,
        linkSourceEnumId: link.linkSourceEnumId, linkSource: nameOf('moqui.basic.Enumeration', 'enumId', link.linkSourceEnumId),
        completeOnMerge: link.completeOnMerge === 'Y'})
}

completedIdList = []
const mr = ec.entity.find('moqui.resource.GitMergeRequest').condition('mergeRequestId', mergeRequestId).disableAuthz().one()
if (mr == null || mr.statusId !== 'GmrMerged') return
for (const link of Array.from(ec.entity.find('mantle.work.effort.WorkEffortGitMergeRequest').condition('mergeRequestId', mergeRequestId)
        .condition('completeOnMerge', 'Y').disableAuthz().list())) {
    ec.message.pushErrors()
    try {
        const out = ec.service.sync().name('mantle.work.GitServices.complete#TaskFromCommit').parameters({workEffortId: link.workEffortId,
            commitId: mr.mergeCommitId || mr.headCommitId}).disableAuthz().call()
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
        if (out?.completed) completedIdList.push(link.workEffortId)
    } catch (err) {
        ec.logger.error(`Merge request ${mergeRequestId}: work item ${link.workEffortId} not completed: ${err && err.message ? err.message : err}`)
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
}

movedIdList = []
const moves = {}
for (const link of Array.from(ec.entity.find('mantle.work.effort.WorkEffortGitMergeRequest').condition('mergeRequestId', mergeRequestId).disableAuthz().list())) {
    const task = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', link.workEffortId).disableAuthz().one()
    if (task == null || !['WeInProgress', 'WeApproved'].includes(task.statusId) || !task.rootWorkEffortId) continue
    if (!(task.rootWorkEffortId in moves)) moves[task.rootWorkEffortId] = ec.service.sync().name('mantle.work.ProjectServices.get#ProjectSettings')
            .parameters({workEffortId: task.rootWorkEffortId}).disableAuthz().call()?.settings?.WstMergeRequestMoves === 'Y'
    if (!moves[task.rootWorkEffortId]) continue
    ec.message.pushErrors()
    try {
        const flow = ec.service.sync().name('mantle.work.TaskServices.get#TaskStatusFlow').parameters({workEffortId: task.workEffortId}).disableAuthz().call()
        if (!Array.from(flow?.transitionList || []).some((transition) => transition.toStatusId === 'WeInReview')) continue
        ec.service.sync().name('mantle.work.TaskServices.set#TaskStatus').parameters({workEffortId: task.workEffortId, statusId: 'WeInReview'}).disableAuthz().call()
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
        movedIdList.push(task.workEffortId)
    } catch (err) {
        ec.logger.error(`Merge request ${mergeRequestId}: work item ${task.workEffortId} not moved to In Review: ${err && err.message ? err.message : err}`)
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
}

const mr = ec.entity.find('moqui.resource.GitMergeRequest').condition('mergeRequestId', mergeRequestId).disableAuthz().one()
if (mr == null) return
const actor = actorUserId || ec.user.userId || null
const rule = (name, run) => {
    ec.message.pushErrors()
    try {
        run()
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
    } catch (err) {
        ec.logger.error(`Merge request ${mergeRequestId} ${action}: ${name} failed: ${err && err.message ? err.message : err}`)
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
}
const call = (name, parameters) => ec.service.sync().name(name).parameters(parameters).disableAuthz().call()
const notify = (kind, change, userIds) => rule('the ' + kind + ' notice', () => call('mantle.work.GitServices.notify#MergeRequest',
        {mergeRequestId, kind, change, actorUserId: actor, userIdList: userIds || null}))
if (['opened', 'updated', 'ready', 'reopened'].includes(action)) rule('the work item links', () => call('mantle.work.GitServices.link#MergeRequestItems', {mergeRequestId}))
if ((action === 'opened' || action === 'ready') && mr.statusId === 'GmrOpen') {
    rule('the move to In Review', () => call('mantle.work.GitServices.move#MergeRequestItemsToReview', {mergeRequestId}))
    notify('review', null, null)
}
if (action === 'review_requested' && mr.statusId === 'GmrOpen') {
    // the reviewers this change asked: requested with the merge request's change
    let asked = userIdList != null ? Array.from(userIdList).map(String) : null
    if (asked == null) {
        const changed = mr.lastUpdatedDate ? Number(mr.lastUpdatedDate) : 0
        asked = Array.from(ec.entity.find('moqui.resource.GitMergeRequestReviewer').condition({mergeRequestId, statusId: 'GmrrRequested'}).disableAuthz().list())
                .filter((row) => row.requestedDate && Math.abs(Number(row.requestedDate) - changed) < 10000).map((row) => row.userId)
    }
    if (asked.length) notify('review', null, asked)
}
if (action === 'merged' && mr.statusId === 'GmrMerged') {
    rule('the work items completed', () => call('mantle.work.GitServices.complete#MergeRequestItems', {mergeRequestId}))
    notify('update', 'merged', null)
}
if (action === 'synchronize') {
    rule('the review threads', () => call('mantle.work.GitServices.refresh#ReviewAnchors', {mergeRequestId}))
    notify('update', 'pushed new commits', null)
}
if (action === 'reviewed') {
    const review = actor ? ec.entity.find('moqui.resource.GitMergeRequestReviewer').condition({mergeRequestId, userId: actor}).disableAuthz().one() : null
    const change = {GmrrApproved: 'approved', GmrrChangesRequested: 'requested changes', GmrrCommented: 'reviewed'}[review?.statusId] || 'reviewed'
    notify('update', change, null)
}
if (action === 'closed') notify('update', 'closed', null)

notifiedUserIdList = []
const mr = ec.entity.find('moqui.resource.GitMergeRequest').condition('mergeRequestId', mergeRequestId).disableAuthz().one()
if (mr == null) return
const reviewers = Array.from(ec.entity.find('moqui.resource.GitMergeRequestReviewer').condition('mergeRequestId', mergeRequestId).disableAuthz().list())
let userIds
if (kind === 'review') userIds = userIdList != null ? Array.from(userIdList).map(String)
        : reviewers.filter((row) => row.statusId === 'GmrrRequested').map((row) => row.userId)
else userIds = [mr.authorUserId].concat(reviewers.map((row) => row.userId))
const actor = actorUserId || ec.user.userId || null
userIds = Array.from(new Set(userIds.filter((id) => id && id !== actor)))
if (!userIds.length) return
const account = actor ? ec.entity.find('moqui.security.UserAccount').condition('userId', actor).useCache(true).disableAuthz().one() : null
const actorName = account ? (account.userFullName || account.username || actor) : 'Moqui'
try {
    const nm = ec.makeNotificationMessage().topic(kind === 'review' ? 'MergeRequestReview' : 'MergeRequestUpdate').userIds(userIds)
            .message({mergeRequestId, mergeRequestNum: mr.mergeRequestNum, title: mr.title, repositoryId: mr.repositoryId,
                sourceRef: mr.sourceRef, targetRef: mr.targetRef, actorName, change: change || null,
                recordEntityName: 'moqui.resource.GitMergeRequest', recordId: mergeRequestId})
    if (typeof nm.record === 'function') nm.record('moqui.resource.GitMergeRequest', mergeRequestId)
    nm.send()
    notifiedUserIdList = userIds
} catch (err) {
    ec.logger.error(`Merge request ${mergeRequestId}: the ${kind} notice not sent: ${err && err.message ? err.message : err}`)
}

notifiedUserIdList = []
const status = ec.entity.find('moqui.resource.GitCommitStatus').condition('commitStatusId', commitStatusId).disableAuthz().one()
if (status == null || !['failure', 'error'].includes(status.state)) return
const repositoryId = status.repositoryId
ec.message.pushErrors()
try {
    const found = ec.service.sync().name('org.moqui.impl.GitServices.get#GitCommit').parameters({repositoryId, commitId: status.commitId, stats: false}).disableAuthz().call()
    const commit = found?.commit || {}
    const userIds = []
    if (commit.moquiUserId) userIds.push(commit.moquiUserId)
    else if (commit.authorEmail) {
        for (const account of Array.from(ec.entity.find('moqui.security.UserAccount').condition('emailAddress', commit.authorEmail)
                .selectField('userId').disableAuthz().list())) userIds.push(account.userId)
    }
    for (const mr of Array.from(ec.entity.find('moqui.resource.GitMergeRequest').condition({repositoryId, headCommitId: status.commitId})
            .condition('statusId', 'in', ['GmrDraft', 'GmrOpen']).disableAuthz().list())) userIds.push(mr.authorUserId)
    const wanted = Array.from(new Set(userIds.filter((id) => id && id !== status.createdByUserId && id !== ec.user.userId)))
    if (wanted.length) {
        ec.makeNotificationMessage().topic('CommitStatusFailed').userIds(wanted).message({repositoryId, commitId: status.commitId,
            shortId: commit.shortId || String(status.commitId).substring(0, 10), summary: commit.summary || '', checkContext: status.context || 'default',
            state: status.state, stateLabel: status.state === 'error' ? 'errored' : 'failed', description: status.description || null,
            targetUrl: status.targetUrl || null}).send()
        notifiedUserIdList = wanted
    }
} catch (err) {
    ec.logger.error(`Commit status ${commitStatusId} of ${repositoryId}: the failure notice not sent: ${err && err.message ? err.message : err}`)
} finally { ec.message.clearErrors(); ec.message.popErrors() }

const mr = ec.entity.find('moqui.resource.GitMergeRequest').condition('mergeRequestId', mergeRequestId).disableAuthz().one()
const access = mr ? ec.service.sync().name('org.moqui.impl.GitServices.get#GitRepositoryAccess').parameters({repositoryId: mr.repositoryId}).call() : null
// a client contact (PROJECT_CLIENT) only views a shared repository: review comments are the team's notes (impl-projects.md P10b)
if (!mr || !access?.canView || !ec.user.userId || ec.user.hasPermission('PROJECT_CLIENT')) {
    ec.message.addError(ec.resource.expand('Merge request ${mergeRequestId} not found', '', {mergeRequestId})); return }
const text = String(body || '').trim()
if (!text) { ec.message.addError(ec.l10n.localize('A comment needs some text')); return }
let parent = null
if (parentCommEventId) {
    parent = ec.entity.find('mantle.party.communication.CommunicationEvent').condition('communicationEventId', parentCommEventId).disableAuthz().one()
    const rootId = parent?.rootCommEventId || parent?.communicationEventId
    const anchored = rootId ? ec.entity.find('mantle.party.communication.CommunicationEventGitAnchor').condition('communicationEventId', rootId).disableAuthz().one() : null
    const filed = rootId ? ec.entity.find('mantle.party.communication.CommunicationEventRecord').condition({communicationEventId: rootId,
        recordEntityName: 'moqui.resource.GitMergeRequest', recordId: mergeRequestId}).disableAuthz().count() : 0
    if (!parent || (!filed && anchored?.mergeRequestId !== mergeRequestId)) { ec.message.addError(ec.resource.expand('Comment ${parentCommEventId} is not of this merge request', '', {parentCommEventId})); return }
}
const where = path ? ' ' + path + (newLine != null ? ':' + newLine : oldLine != null ? ':' + oldLine : '') : ''
communicationEventId = ec.service.sync().name('create#mantle.party.communication.CommunicationEvent').parameters({communicationEventTypeId: 'Comment',
    contactMechTypeEnumId: 'CmtWebForm', statusId: 'CeSent', fromPartyId: ec.user.userAccount?.partyId || null, entryDate: ec.user.nowTimestamp,
    contentType: 'text/markdown', subject: ec.resource.expand('Review of !${num}${where}', '', {num: mr.mergeRequestNum, where}), body: text,
    parentCommEventId: parent?.communicationEventId || null, rootCommEventId: parent ? (parent.rootCommEventId || parent.communicationEventId) : null}).disableAuthz().call()?.communicationEventId
if (ec.message.hasError() || !communicationEventId) return
if (!parent) {
    const wasDisabled = ec.artifactExecution.disableAuthz()
    try {
        ec.service.sync().name('create#mantle.party.communication.CommunicationEventRecord').parameters({communicationEventId,
            recordEntityName: 'moqui.resource.GitMergeRequest', recordId: mergeRequestId, linkedByUserId: ec.user.userId, linkedDate: ec.user.nowTimestamp}).call()
    } finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }
    if (path) ec.service.sync().name('mantle.work.GitServices.store#ReviewAnchor').parameters({communicationEventId, mergeRequestId, path,
        oldLine: oldLine ?? null, newLine: newLine ?? null, lineText: lineText || null}).call()
    if (ec.message.hasError()) return
}
ec.message.pushErrors()
try {
    ec.service.sync().name('mantle.work.GitServices.notify#MergeRequest').parameters({mergeRequestId, kind: 'update', change: 'commented'}).disableAuthz().call()
} catch (err) { ec.logger.error(`Merge request ${mergeRequestId}: the comment notice not sent: ${err}`) }
finally { ec.message.clearErrors(); ec.message.popErrors() }

const mr = ec.entity.find('moqui.resource.GitMergeRequest').condition('mergeRequestId', mergeRequestId).disableAuthz().one()
const access = mr ? ec.service.sync().name('org.moqui.impl.GitServices.get#GitRepositoryAccess').parameters({repositoryId: mr.repositoryId}).call() : null
if (!mr || !access?.canView || ec.user.hasPermission('PROJECT_CLIENT')) {
    ec.message.addError(ec.resource.expand('Merge request ${mergeRequestId} not found', '', {mergeRequestId})); return }
if (oldLine == null && newLine == null) { ec.message.addError(ec.l10n.localize('A review comment is on an old or a new line')); return }
const filed = ec.entity.find('mantle.party.communication.CommunicationEventRecord').condition({communicationEventId,
    recordEntityName: 'moqui.resource.GitMergeRequest', recordId: mergeRequestId}).disableAuthz().count()
if (!filed) { ec.message.addError(ec.resource.expand('Comment ${communicationEventId} is not filed on the merge request', '', {communicationEventId})); return }
const fields = {communicationEventId, mergeRequestId, repositoryId: mr.repositoryId, commitId: commitId || mr.headCommitId || null,
    path: String(path), oldLine: oldLine ?? null, newLine: newLine ?? null, lineText: lineText ? String(lineText).substring(0, 255) : null, outdated: 'N'}
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    const row = ec.entity.find('mantle.party.communication.CommunicationEventGitAnchor').condition('communicationEventId', communicationEventId).one()
    if (row) { row.setFields(fields, true, null, null); row.update() }
    else ec.service.sync().name('create#mantle.party.communication.CommunicationEventGitAnchor').parameters(fields).call()
} finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }

const event = ec.entity.find('mantle.party.communication.CommunicationEvent').condition('communicationEventId', communicationEventId).disableAuthz().one()
rootCommEventId = event ? (event.rootCommEventId || event.communicationEventId) : null
const anchor = rootCommEventId ? ec.entity.find('mantle.party.communication.CommunicationEventGitAnchor').condition('communicationEventId', rootCommEventId).disableAuthz().one() : null
const mr = anchor ? ec.entity.find('moqui.resource.GitMergeRequest').condition('mergeRequestId', anchor.mergeRequestId).disableAuthz().one() : null
const access = mr ? ec.service.sync().name('org.moqui.impl.GitServices.get#GitRepositoryAccess').parameters({repositoryId: mr.repositoryId}).call() : null
if (!access?.canView || !ec.user.userId || ec.user.hasPermission('PROJECT_CLIENT')) {
    ec.message.addError(ec.resource.expand('Review thread ${communicationEventId} not found', '', {communicationEventId})); return }
const root = ec.entity.find('mantle.party.communication.CommunicationEvent').condition('communicationEventId', rootCommEventId).disableAuthz().one()
const statusId = resolved ? 'CeResolved' : 'CeSent'
if (root.statusId === statusId) return
root.statusId = statusId
root.update()

threadList = []
const mr = ec.entity.find('moqui.resource.GitMergeRequest').condition('mergeRequestId', mergeRequestId).disableAuthz().one()
const access = mr ? ec.service.sync().name('org.moqui.impl.GitServices.get#GitRepositoryAccess').parameters({repositoryId: mr.repositoryId}).call() : null
if (!mr || !access?.canView) { ec.message.addError(ec.resource.expand('Merge request ${mergeRequestId} not found', '', {mergeRequestId})); return }
// a client contact (PROJECT_CLIENT) who views a shared repository reads its diffs, never the team's review threads
// (Comments, as a note; impl-projects.md P10b)
if (ec.user.hasPermission('PROJECT_CLIENT')) return
let find = ec.entity.find('mantle.party.communication.CommunicationEventGitAnchor').condition('mergeRequestId', mergeRequestId).disableAuthz()
if (path) find = find.condition('path', path)
const names = {}
const nameOf = (partyId) => {
    if (!partyId) return ''
    if (!(partyId in names)) {
        const party = ec.entity.find('mantle.party.PartyDetail').condition('partyId', partyId).disableAuthz().one()
        names[partyId] = party ? (party.organizationName || [party.firstName, party.lastName].filter((part) => part).join(' ') || partyId) : partyId
    }
    return names[partyId]
}
const entry = (event) => ({communicationEventId: event.communicationEventId, parentCommEventId: event.parentCommEventId || null,
    fromPartyId: event.fromPartyId, authorName: nameOf(event.fromPartyId), entryDate: event.entryDate, body: event.body || ''})
for (const anchor of Array.from(find.orderBy('path').orderBy('newLine').orderBy('oldLine').list())) {
    const root = ec.entity.find('mantle.party.communication.CommunicationEvent').condition('communicationEventId', anchor.communicationEventId).disableAuthz().one()
    if (root == null) continue
    const replies = Array.from(ec.entity.find('mantle.party.communication.CommunicationEvent').condition('rootCommEventId', root.communicationEventId)
            .condition('communicationEventId', 'not-equals', root.communicationEventId).orderBy('entryDate').disableAuthz().list())
    threadList.push({communicationEventId: root.communicationEventId, path: anchor.path, oldLine: anchor.oldLine, newLine: anchor.newLine,
        lineText: anchor.lineText, commitId: anchor.commitId, outdated: anchor.outdated === 'Y', resolved: root.statusId === 'CeResolved',
        commentList: [entry(root)].concat(replies.map(entry))})
}

outdatedCount = 0
const mr = ec.entity.find('moqui.resource.GitMergeRequest').condition('mergeRequestId', mergeRequestId).disableAuthz().one()
if (mr == null || !mr.headCommitId) return
const anchors = Array.from(ec.entity.find('mantle.party.communication.CommunicationEventGitAnchor').condition('mergeRequestId', mergeRequestId)
        .condition('outdated', 'not-equals', 'Y').disableAuthz().list()).filter((anchor) => anchor.commitId && anchor.commitId !== mr.headCommitId && anchor.newLine != null)
const compares = {}
for (const anchor of anchors) {
    ec.message.pushErrors()
    try {
        if (!(anchor.commitId in compares)) compares[anchor.commitId] = ec.service.sync().name('org.moqui.impl.GitServices.get#GitCompare')
                .parameters({repositoryId: mr.repositoryId, base: anchor.commitId, head: mr.headCommitId, withDiffs: true}).disableAuthz().call()
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
        const file = Array.from(compares[anchor.commitId]?.fileList || []).find((one) => one.path === anchor.path)
        let changed = false
        if (file) changed = file.changeType === 'deleted' || Array.from(file.hunks || []).some((hunk) => Array.from(hunk.lines || [])
                .some((line) => line.tag === 'delete' && Number(line.oldNo) === Number(anchor.newLine)))
        if (changed) { anchor.outdated = 'Y'; anchor.update(); outdatedCount++ }
    } catch (err) {
        ec.logger.error(`Merge request ${mergeRequestId}: review thread ${anchor.communicationEventId} not checked: ${err && err.message ? err.message : err}`)
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
}

const task = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).one()
if (task == null || task.workEffortTypeEnumId !== 'WetTask') { ec.message.addError(ec.resource.expand('Work item ${workEffortId} not found', '', {workEffortId})); return }
const projectId = task.rootWorkEffortId || ''
pattern = projectId ? ec.service.sync().name('mantle.work.ProjectServices.get#ProjectSettings').parameters({workEffortId: projectId}).call()?.settings?.WstBranchPattern || null : null
if (!pattern) pattern = '<id>-<words>'
const words = String(task.workEffortName || '').toLowerCase().normalize('NFKD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, ' ')
        .trim().split(/\s+/).filter((word) => word).slice(0, 6).join('-')
const id = String(workEffortId)
const type = {WepFix: 'fix', WepNewFeature: 'feature', WepFeatureEnhance: 'feature', WepDocument: 'docs'}[task.purposeEnumId] || 'task'
let name = String(pattern).replace(/<id>/g, id).replace(/<KEY>/g, projectId).replace(/<key>/g, projectId.toLowerCase())
        .replace(/<n>/g, id.includes('-') ? id.substring(id.lastIndexOf('-') + 1) : id).replace(/<words>/g, words).replace(/<type>/g, type)
name = name.replace(/[^A-Za-z0-9._\/-]+/g, '-').replace(/-{2,}/g, '-').replace(/\/{2,}/g, '/').replace(/^[-/.]+|[-/.]+$/g, '')
branchName = name.substring(0, 100).replace(/[-/.]+$/, '')

const task = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).one()
if (task == null || task.workEffortTypeEnumId !== 'WetTask') { ec.message.addError(ec.resource.expand('Work item ${workEffortId} not found', '', {workEffortId})); return }
const linked = task.rootWorkEffortId ? Array.from(ec.entity.find('mantle.work.effort.WorkEffortGitRepository').condition('workEffortId', task.rootWorkEffortId)
        .conditionDate('fromDate', 'thruDate', null).disableAuthz().list()).map((row) => row.repositoryId) : []
if (!repositoryId) {
    const repos = Array.from(new Set(linked))
    if (repos.length !== 1) { ec.message.addError(repos.length ? ec.l10n.localize('Choose the repository for the branch') : ec.l10n.localize('The project has no repository')); return }
    repositoryId = repos[0]
}
if (!branchName) branchName = ec.service.sync().name('mantle.work.GitServices.get#TaskBranchName').parameters({workEffortId}).call()?.branchName
if (ec.message.hasError() || !branchName) return
const out = ec.service.sync().name('org.moqui.impl.GitServices.create#GitRef').parameters({repositoryId, refName: String(branchName).trim(),
    refType: 'branch', revision: fromRef || null}).call()
if (ec.message.hasError()) return
refName = out?.refName || 'refs/heads/' + branchName
commitId = out?.commitId || null
ec.service.sync().name('mantle.work.GitServices.store#WorkEffortRef').parameters({workEffortId, repositoryId, refName, objectId: commitId,
    linkSourceEnumId: 'WglsBranchName'}).disableAuthz().call()

resultList = []
const term = String(text || '').trim()
if (!term) return
const max = Math.max(1, Math.min(Number(limit) || 5, 50))
const number = /^[!#]?(\d+)$/.exec(term)
const bang = term.startsWith('!')
const words = bang ? term.substring(1).trim() : term
if (!bang) {
    const repos = ec.service.sync().name('org.moqui.impl.GitServices.find#GitRepositories').parameters({text: words, pageSize: max}).call()
    for (const repo of Array.from(repos?.repositoryList || [])) resultList.push({kind: 'repository', repositoryId: repo.repositoryId,
        description: repo.description || '', repositoryKind: repo.repositoryKind})
}
if (resultList.length >= max || (!number && !words)) return
const visible = Array.from(ec.service.sync().name('org.moqui.impl.GitServices.find#GitRepositories').parameters({pageNoLimit: true}).call()?.repositoryList || [])
        .map((repo) => repo.repositoryId)
if (!visible.length) return
let rows
if (number) {
    rows = Array.from(ec.entity.find('moqui.resource.GitMergeRequest').condition('repositoryId', 'in', visible).condition('mergeRequestNum', Number(number[1]))
            .orderBy('-lastUpdatedDate').limit(max - resultList.length).disableAuthz().list())
} else {
    rows = Array.from(ec.entity.find('moqui.resource.GitMergeRequest').condition('repositoryId', 'in', visible)
            .condition(ec.entity.conditionFactory.makeCondition('title', 'like', '%' + words + '%').ignoreCase())
            .orderBy('-lastUpdatedDate').limit(max - resultList.length).disableAuthz().list())
}
for (const mr of rows) resultList.push({kind: 'mergeRequest', repositoryId: mr.repositoryId, mergeRequestId: mr.mergeRequestId,
    mergeRequestNum: mr.mergeRequestNum, title: mr.title, statusId: mr.statusId, sourceRef: mr.sourceRef, targetRef: mr.targetRef, description: ''})

authzTypeEnumId = 'AUTHZT_NONE'
const action = authzActionEnumId
if (!userId || !['AUTHZA_VIEW', 'AUTHZA_CREATE', 'AUTHZA_UPDATE', 'AUTHZA_DELETE'].includes(action)) return
const account = ec.entity.find('moqui.security.UserAccount').condition('userId', userId).useCache(true).disableAuthz().one()
if (!account?.partyId) return
const projectIds = Array.from(ec.entity.find('mantle.work.effort.WorkEffortGitRepository').condition('repositoryId', artifactName)
        .conditionDate('fromDate', 'thruDate', null).disableAuthz().list()).map((link) => link.workEffortId)
if (!projectIds.length) return
// a client contact who signs in (PROJECT_CLIENT; impl-projects.md P10): only views, and only a repository of one of its
// client projects that shares its repositories (its own party's or its organization's client role), whatever other
// role its party holds; a failed check gives nothing
const client = ec.service.sync().name('mantle.work.ProjectServices.get#ClientProjectInfo').parameter('userId', userId).call()
if (ec.message.hasError() || client == null) return
if (client.isClient) {
    if (action === 'AUTHZA_VIEW' && projectIds.some((id) => Array.from(client.shareRepositoryProjectIds || []).includes(id)))
        authzTypeEnumId = 'AUTHZT_ALLOW'
    return
}
const roles = Array.from(ec.entity.find('mantle.work.effort.WorkEffortParty').condition('workEffortId', 'in', projectIds)
        .condition('partyId', account.partyId).conditionDate('fromDate', 'thruDate', null).disableAuthz().list())
if (!roles.length) return
const clientRoles = ['Customer', 'CustomerBillTo', 'ClientManager', 'ClientBilling']
const leadRoles = ['ProjectManager', 'Manager', 'ProgrammerLead', 'SysArchitect']
const internal = roles.filter((row) => !clientRoles.includes(row.roleTypeId))
if (internal.length) {
    if (action !== 'AUTHZA_DELETE' || internal.some((row) => leadRoles.includes(row.roleTypeId))) authzTypeEnumId = 'AUTHZT_ALLOW'
    return
}
if (action !== 'AUTHZA_VIEW') return
const clientProjectIds = Array.from(new Set(roles.map((row) => row.workEffortId)))
const shared = ec.entity.find('mantle.work.effort.WorkEffortSetting').condition('workEffortId', 'in', clientProjectIds)
        .condition('settingTypeEnumId', 'WstShareRepositories').condition('settingValue', 'Y').disableAuthz().count()
if (shared > 0) authzTypeEnumId = 'AUTHZT_ALLOW'
